def chi(part, cyc):
    part=tuple(part); cyc=tuple(sorted(cyc, reverse=True))
    if sum(part)!=sum(cyc): return 0
    if not cyc: return 1 if not part else 0
    k=cyc[0]
    total=0
    for newp,ht in border_strips(part,k):
        total += ((-1)**(ht-1))*chi(newp, cyc[1:])
    return total

